'use strict';
globalThis.createMapStudio=function(api){
  const {esc,toast}=api;let dirty=false,pending=false;
  function render(parentId=''){
    dirty=false;const world=api.getDraft(),maps=(world.scenes||[]).filter(s=>s.mode==='map');
    const childIds=new Set(maps.flatMap(s=>s.hotspots.map(p=>p.sceneId).filter(id=>maps.some(m=>m.id===id))));
    function node(map){const children=map.hotspots.map(p=>maps.find(m=>m.id===p.sceneId)).filter(Boolean),asset=api.getAsset(map.imageKey),src=asset?.url||map.imageUrl;return `<li><article class="map-manager-card"><div class="map-manager-thumb">${src?`<img src="${esc(src)}" alt="Imagem de ${esc(map.title)}">`:'<span aria-hidden="true">⌖</span>'}</div><div class="map-manager-info"><h3>${esc(map.title)}</h3><p>${children.length} região(ões) dentro deste mapa · ${map.hotspots.length} ponto(s)</p><small>${map.unlockChapter?'Abre após a etapa '+map.unlockChapter:'Disponível desde a entrada'}</small><div class="world-actions"><a class="world-button ghost" href="#map-editor/${map.id}">Editar mapa</a><a class="world-text-link" href="#maps-studio/${map.id}">Adicionar região dentro ↗</a></div></div></article>${children.length?'<ul>'+children.map(node).join('')+'</ul>':''}</li>`;}
    document.querySelector('#content').innerHTML=`<section class="world-section map-studio"><a class="world-text-link" href="#world-studio">← Estúdio de mundos</a><header class="world-heading"><p class="world-eyebrow">AUTORIA / MAPAS</p><h1>Monte seu mundo em camadas.</h1><p>Crie um mapa principal e adicione regiões dentro dele. Cada região pode ter sua própria imagem e novos lugares.</p></header><p class="world-editor-notice">Aqui você vê e edita todos os mapas, mesmo antes de desbloqueá-los como leitor. Salve as alterações e publique no Estúdio de mundos para aplicá-las à experiência deste navegador.</p><div class="map-manager-layout"><section><h2>Seus mapas e regiões</h2><p class="world-muted">No exemplo: Ayîvernî contém Pentateeri, que contém Sahkiz. Clique em Editar mapa para enviar a imagem e posicionar cada região.</p><ul class="map-tree">${maps.filter(m=>!childIds.has(m.id)).map(node).join('')||'<li>Nenhum mapa criado. Comece pelo mapa do seu mundo.</li>'}</ul></section><aside class="world-editor-panel"><form id="mapCreateForm"><p class="world-eyebrow">ADICIONAR AO MUNDO</p><h2>Criar mapa ou região</h2><label>Dentro de qual mapa?<select name="parentId"><option value="">Nenhum · criar mapa principal</option>${maps.map(m=>`<option value="${m.id}" ${m.id===parentId?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><label>Criar ou aproveitar um mapa?<select name="existingId"><option value="">Criar um novo mapa</option>${maps.map(m=>`<option value="${m.id}">Usar ${esc(m.title)}</option>`).join('')}</select></label><label>Nome do novo mapa ou região<input name="title" required maxlength="160" placeholder="Ex.: Pentateeri"></label><label>Informações ao clicar na região<textarea name="body" rows="3" maxlength="4000" placeholder="O que o leitor encontra neste lugar?"></textarea></label><label>Imagem do novo mapa · opcional<input name="image" type="file" accept="image/*"></label><p class="world-muted">Envie até 25 MB. Você também pode enviar a imagem depois em Editar mapa.</p><label>Revelar ao leitor<select name="stage"><option value="0">Desde a entrada</option>${world.chapters.map((c,i)=>`<option value="${i+1}">Após ${esc(c.title)}</option>`).join('')}</select></label><p class="world-muted">A região respeita a etapa de abertura do mapa que a contém. O ponto nasce no centro: depois, clique na imagem no editor para reposicioná-lo.</p><button type="submit" class="world-button gold">Criar e abrir mapa</button><p role="status" id="mapCreateStatus"></p></form></aside></div><div class="world-actions"><a class="world-button gold" href="#world-studio">Publicar a experiência ↗</a><a class="world-button ghost" href="#scenes">Ver como leitor ↗</a></div></section>`;
    const form=document.querySelector('#mapCreateForm');
    form.addEventListener('input',()=>{dirty=true;});
    form.elements.existingId.onchange=()=>{const existing=Boolean(form.elements.existingId.value);form.elements.title.required=!existing;form.elements.title.disabled=existing;form.elements.image.disabled=existing;};
    form.onsubmit=async e=>{
      e.preventDefault();if(pending)return;
      const f=new FormData(form),options={id:'map-'+crypto.randomUUID(),pointId:'region-'+crypto.randomUUID(),parentId:String(f.get('parentId')||''),existingId:String(f.get('existingId')||''),title:String(f.get('title')||'').trim(),body:String(f.get('body')||'').trim(),stage:Number(f.get('stage'))};
      let candidate=LenoraScenes.mapCandidate(api.getDraft(),options);if(candidate.error){document.querySelector('#mapCreateStatus').textContent=candidate.error;return toast(candidate.error);}
      const file=form.elements.image.files[0];pending=true;form.querySelector('button').disabled=true;
      try{
        if(file&&!options.existingId){options.imageKey='world-'+crypto.randomUUID()+'-image';await api.putAsset(options.imageKey,file);candidate=LenoraScenes.mapCandidate(api.getDraft(),options);}
        if(candidate.error)throw Error(candidate.error);
        if(!api.saveMaps(candidate.scenes))throw Error('Não foi possível salvar os mapas. Suas alterações anteriores foram mantidas.');
        dirty=false;pending=false;location.hash='map-editor/'+candidate.id;toast(options.parentId?'Região criada dentro do mapa. Reposicione seu ponto no mapa de origem quando quiser.':'Mapa principal criado. Agora você pode adicionar suas regiões.');
      }catch(error){document.querySelector('#mapCreateStatus').textContent=error.message;toast(error.message);}
      finally{pending=false;form.querySelector('button').disabled=false;}
    };
  }
  return{render,hasUnsaved:()=>Boolean(document.querySelector('#mapCreateForm'))&&dirty,isBusy:()=>pending};
};
